import unittest
from candidate import all_prefixes

class TestAllPrefixes(unittest.TestCase):
    def test_all_prefixes_normal_case(self):
        self.assertEqual(all_prefixes('abc'), ['a', 'ab', 'abc'])

    def test_all_prefixes_empty_string(self):
        self.assertEqual(all_prefixes(''), [])

    def test_all_prefixes_single_character(self):
        self.assertEqual(all_prefixes('a'), ['a'])

    def test_all_prefixes_long_string(self):
        self.assertEqual(all_prefixes('abcdefghij'), ['a', 'ab', 'abc', 'abcd', 'abcde', 'abcdef', 'abcdefg', 'abcdefghi', 'abcdefghij'])

    def test_all_prefixes_input_none(self):
        with self.assertRaises(TypeError):
            all_prefixes(None)

    def test_all_prefixes_input_not_string(self):
        with self.assertRaises(TypeError):
            all_prefixes(123)

    def test_all_prefixes_input_list(self):
        with self.assertRaises(TypeError):
            all_prefixes(['a', 'b', 'c'])

if __name__ == '__main__':
    unittest.main()
